// TestAccBookmark_boardReportLifecycleMock: board-type bookmarks (insights/
// retention/funnels/flows) must be created through the dashboards content
// PATCH (never POST /bookmarks, which silently drops dashboard_id), updated
// via the standalone bookmark PATCH, moved between boards only by
// replacement, and deleted through the content-delete PATCH.
func TestAccBookmark_boardReportLifecycleMock(t *testing.T) {
	srv := newMockServer(t, mockOpts{enveloped: true, idField: "id", stringID: false, resultsMap: false, upsert: false, listCreate: false})

	// assertContentCreatePath proves the create went through the dashboards
	// content PATCH and that no standalone POST /bookmarks was issued.
	assertContentCreatePath := func(*terraform.State) error {
		sawContentCreate := false
		for _, cr := range srv.requests("PATCH") {
			if !strings.Contains(cr.path, "/dashboards/") {
				continue
			}
			if c, ok := cr.body["content"].(map[string]any); ok {
				if a, _ := c["action"].(string); a == "create" {
					sawContentCreate = true
				}
			}
		}
		if !sawContentCreate {
			return fmt.Errorf("no dashboards content-create PATCH was captured")
		}
		for _, cr := range srv.requests("POST") {
			if strings.HasSuffix(strings.TrimRight(cr.path, "/"), "/bookmarks") {
				return fmt.Errorf("board-type bookmark was created via standalone POST %s (must use the dashboards content PATCH)", cr.path)
			}
		}
		return nil
	}

	resource.Test(t, resource.TestCase{
		ProtoV6ProviderFactories: testProtoV6,
		Steps: []resource.TestStep{
			{
				// Create through the content PATCH; the implicit post-apply
				// refresh+plan asserts idempotency (params round-trip through the
				// GET's stringified-params form).
				Config: bookmarkBoardConfig(srv.URL, "report-a", "board_a"),
				Check: resource.ComposeTestCheckFunc(
					resource.TestCheckResourceAttr("mixpanel_bookmark.test", "name", "report-a"),
					resource.TestCheckResourceAttr("mixpanel_bookmark.test", "type", "insights"),
					resource.TestCheckResourceAttrPair("mixpanel_bookmark.test", "dashboard_id", "mixpanel_dashboard.board_a", "id"),
					assertContentCreatePath,
				),
			},
			{
				// Rename in place: the standalone bookmark PATCH still works for
				// name/params updates.
				Config: bookmarkBoardConfig(srv.URL, "report-b", "board_a"),
				Check:  resource.TestCheckResourceAttr("mixpanel_bookmark.test", "name", "report-b"),
				ConfigPlanChecks: resource.ConfigPlanChecks{
					PreApply: []plancheck.PlanCheck{
						plancheck.ExpectResourceAction("mixpanel_bookmark.test", plancheck.ResourceActionUpdate),
					},
				},
			},
			{
				// Changing dashboard_id is a board MOVE, which the API cannot do
				// in place (the standalone PATCH half-moves) -> replacement, which
				// exercises the content-delete on board A and a content-create on
				// board B. The final destroy exercises content-delete again.
				Config: bookmarkBoardConfig(srv.URL, "report-b", "board_b"),
				Check: resource.ComposeTestCheckFunc(
					resource.TestCheckResourceAttrPair("mixpanel_bookmark.test", "dashboard_id", "mixpanel_dashboard.board_b", "id"),
				),
				ConfigPlanChecks: resource.ConfigPlanChecks{
					PreApply: []plancheck.PlanCheck{
						plancheck.ExpectResourceAction("mixpanel_bookmark.test", plancheck.ResourceActionDestroyBeforeCreate),
					},
				},
			},
		},
	})
}
